package cn.zhuatech.marketingai.controller; import cn.zhuatech.marketingai.common.ApiResponse; import cn.zhuatech.marketingai.service.CampaignBriefService; import jakarta.validation.Valid; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/ai") @PreAuthorize("hasAnyRole('DOMAIN_USER','DOMAIN_OPERATOR','ADMIN')") public class AiFeatureController { private final CampaignBriefService service; public AiFeatureController(CampaignBriefService service){this.service=service;} @PostMapping("/campaign/brief") public ApiResponse<CampaignBriefService.Result> execute(@Valid @RequestBody CampaignBriefService.Request request){return ApiResponse.ok("营销 Brief 与品牌检查完成",service.build(request));} }